import os
import re
from typing import List, Dict, Any

import requests


class TextContentSafety:
    """
    Text content safety checker/redactor using OpenAI Moderation API.
    Requires OPENAI_API_KEY to be set in the environment.
    """

    API_URL = "https://api.openai.com/v1/moderations"
    MODEL = "omni-moderation-latest"

    def __init__(self, api_key: str | None = None):
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY is required")

    def _moderate(self, text: str) -> Dict[str, Any]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        payload = {
            "model": self.MODEL,
            "input": text,
        }
        resp = requests.post(self.API_URL, headers=headers, json=payload, timeout=30)
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def _flagged_categories(result: Dict[str, Any]) -> List[str]:
        categories = result.get("categories", {})
        return [k for k, v in categories.items() if v]

    @staticmethod
    def _heuristic_spans(text: str) -> List[Dict[str, int]]:
        # Basic span detection for common high-risk patterns when API does not return spans.
        patterns = [
            r"\b(?:kill|murder|suicide|bomb|explosive|terrorist)\b",
            r"\b(?:porn|explicit|rape|sexual assault)\b",
            r"\b(?:hate|slur|racist|nazi)\b",
        ]
        spans = []
        for pat in patterns:
            for m in re.finditer(pat, text, flags=re.IGNORECASE):
                spans.append({"start": m.start(), "end": m.end()})
        spans.sort(key=lambda x: (x["start"], x["end"]))
        merged = []
        for s in spans:
            if not merged or s["start"] > merged[-1]["end"]:
                merged.append(s)
            else:
                merged[-1]["end"] = max(merged[-1]["end"], s["end"])
        return merged

    def check(self, text: str) -> Dict[str, Any]:
        data = self._moderate(text)
        results = data.get("results", [])
        if not results:
            return {"unsafe": False, "categories": [], "spans": []}

        result = results[0]
        unsafe = bool(result.get("flagged", False))
        categories = self._flagged_categories(result)

        spans = result.get("category_scores_spans") or result.get("spans") or []
        normalized_spans = []
        for span in spans:
            if isinstance(span, dict) and "start" in span and "end" in span:
                normalized_spans.append({"start": int(span["start"]), "end": int(span["end"])})
        if unsafe and not normalized_spans:
            normalized_spans = self._heuristic_spans(text)

        return {
            "unsafe": unsafe,
            "categories": categories,
            "spans": normalized_spans,
        }

    def redact(self, text: str, replacement: str = "[REDACTED]") -> Dict[str, Any]:
        assessment = self.check(text)
        spans = assessment["spans"]
        if not spans:
            return {
                "text": text,
                "unsafe": assessment["unsafe"],
                "categories": assessment["categories"],
                "redacted_text": text,
            }

        redacted_parts = []
        last = 0
        for span in spans:
            start, end = max(0, span["start"]), min(len(text), span["end"])
            if start > last:
                redacted_parts.append(text[last:start])
            redacted_parts.append(replacement)
            last = max(last, end)
        if last < len(text):
            redacted_parts.append(text[last:])

        return {
            "text": text,
            "unsafe": assessment["unsafe"],
            "categories": assessment["categories"],
            "redacted_text": "".join(redacted_parts),
        }
